package android.content; import android.content.pm.*; public class Context {final String pkg; final PackageManager pm; public Context(String p,byte[] c){pkg=p;pm=new PackageManager(p,c);}public Context getApplicationContext(){return this;}public String getPackageName(){return pkg;}public PackageManager getPackageManager(){return pm;}public ApplicationInfo getApplicationInfo(){return pm.getApplicationInfo(pkg,0);}}